1	import { createClient } from "@/lib/supabase/server";
2	import type { LookDraft, WeatherPayload } from "@/lib/generator/types";
3	import type { StoredLook } from "./reassemble";
4	import { freshIndexStart, isWornToday } from "./wear";
5	
6	/** Today's stored set for one occasion, in the order the stylist chose. */
7	export async function loadDailyLooks(
8	  userId: string,
9	  occasion: string,
10	  generatedOn: string,
11	): Promise<StoredLook[] | null> {
12	  const supabase = await createClient();
13	  const { data } = await supabase
14	    .from("outfits")
15	    // `wear_logs(worn_on)` is the reverse of wear_logs.outfit_id. A look the
16	    // user has already worn today stays in the set and is badged, rather than
17	    // disappearing the moment they tap the button.
18	    .select("id, look_name, ai_reasoning, layout, look_index, wear_logs(worn_on)")
19	    .eq("user_id", userId)
20	    .eq("occasion", occasion)
21	    .eq("generated_on", generatedOn)
22	    .order("look_index", { ascending: true });
23	
24	  if (!data || data.length === 0) return null;
25	
26	  return data.map((row) => {
27	    const layout = (row.layout ?? {}) as {
28	      anchorIndex?: number;
29	      pieces?: StoredLook["pieces"];
30	    };
31	    return {
32	      id: row.id,
33	      lookName: row.look_name ?? "",
34	      why: row.ai_reasoning ?? "",
35	      anchorIndex: layout.anchorIndex ?? 0,
36	      pieces: layout.pieces ?? [],
37	      worn: isWornToday(row.wear_logs ?? [], generatedOn),
38	    };
39	  });
40	}
41	
42	/**
43	 * Replace today's set for one occasion. Delete-then-insert rather than upsert:
44	 * a regenerate may return a different NUMBER of looks, and leftovers from the
45	 * previous set must not survive alongside the new one.
46	 *
47	 * One exception, and it is the reason this function can be called at all after
48	 * a wear: an outfit with a wear log is PINNED. `wear_logs.outfit_id` used to
49	 * have no ON DELETE action, so deleting a worn outfit raised a foreign-key
50	 * violation and the whole regeneration failed. Pinning is also the honest
51	 * product behaviour — what you actually wore today is not a suggestion to be
52	 * thrown away, so it keeps its place in the day's set and the fresh looks are
53	 * numbered past it (`outfits_daily_unique` covers `look_index`).
54	 *
55	 * Returns the new outfit ids, aligned with the `looks` array.
56	 */
57	export async function saveDailyLooks(
58	  userId: string,
59	  occasion: string,
60	  generatedOn: string,
61	  weather: WeatherPayload,
62	  looks: LookDraft[],
63	): Promise<string[]> {
64	  const supabase = await createClient();
65	
66	  const { data: existing } = await supabase
67	    .from("outfits")
68	    .select("id, look_index, wear_logs(worn_on)")
69	    .eq("user_id", userId)
70	    .eq("occasion", occasion)
